recall.code:
use std::sync::mpsc;
let (tx, rx) = mpsc::channel();
let msg = String::from("hi");
tx.send(msg).unwrap();
println!("{msg}");

use std::sync::mpsc;
let (tx, rx) = mpsc::channel::<String>();
drop(rx);
let err = tx.send(String::from("hi")).unwrap_err();
println!("{}", err.0);
